// NewGit device sign-in.
//
// The account key is an ECDSA P-256 key generated by WebCrypto with
// extractable=false, so no script (including this one) can ever read the
// private key. The CryptoKey object lives in this browser's IndexedDB on this
// device only. Signing a one-time server challenge proves possession.
(function () {
  "use strict";
  var DB = "newgit-device", STORE = "keys", KEY = "device";
  var SIGNED_OUT = "newgit-signed-out";

  function idb() {
    return new Promise(function (resolve, reject) {
      var req = indexedDB.open(DB, 1);
      req.onupgradeneeded = function () { req.result.createObjectStore(STORE); };
      req.onsuccess = function () { resolve(req.result); };
      req.onerror = function () { reject(req.error); };
    });
  }
  function idbOp(mode, fn) {
    return idb().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(STORE, mode);
        var req = fn(tx.objectStore(STORE));
        tx.oncomplete = function () { resolve(req && req.result); };
        tx.onerror = function () { reject(tx.error); };
      });
    });
  }
  function loadKey() { return idbOp("readonly", function (s) { return s.get(KEY); }); }
  function saveKey(v) { return idbOp("readwrite", function (s) { return s.put(v, KEY); }); }
  function deleteKey() { return idbOp("readwrite", function (s) { return s.delete(KEY); }); }

  function b64url(buf) {
    var bin = "", bytes = new Uint8Array(buf);
    for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }
  function sha256(str) { return crypto.subtle.digest("SHA-256", new TextEncoder().encode(str)); }
  function thumbprint(x, y) {
    return sha256('{"crv":"P-256","kty":"EC","x":"' + x + '","y":"' + y + '"}').then(b64url);
  }
  function message(purpose, nonce) { return new TextEncoder().encode("newgit-device-auth:v1|" + purpose + "|" + nonce); }

  function challenge() {
    return fetch("/-/auth/challenge", { credentials: "same-origin", cache: "no-store" }).then(function (r) { return r.json(); }).then(function (j) { return j.nonce; });
  }
  function sign(privateKey, purpose, nonce) {
    return crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, privateKey, message(purpose, nonce)).then(b64url);
  }
  function post(url, body) {
    return fetch(url, { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) })
      .then(function (r) { return r.json().then(function (j) { j._status = r.status; return j; }); });
  }

  function login(stored) {
    return challenge().then(function (nonce) {
      return sign(stored.privateKey, "login", nonce).then(function (sig) {
        return post("/-/auth/login", { id: stored.id, nonce: nonce, sig: sig });
      });
    });
  }

  function register(username) {
    var keys, x, y, id;
    return crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"])
      .then(function (k) { keys = k; return crypto.subtle.exportKey("jwk", k.publicKey); })
      .then(function (jwk) { x = jwk.x; y = jwk.y; return thumbprint(x, y); })
      .then(function (t) { id = t; return challenge(); })
      .then(function (nonce) {
        return sign(keys.privateKey, "register", nonce).then(function (sig) {
          return post("/-/auth/register", { username: username, x: x, y: y, nonce: nonce, sig: sig });
        });
      })
      .then(function (res) {
        if (res._status !== 200) throw new Error(res.error || "registration failed");
        return saveKey({ id: id, username: res.username, privateKey: keys.privateKey, publicKey: keys.publicKey, created: Date.now() }).then(function () { return res; });
      });
  }

  function setStatus(text, isError) {
    var el = document.getElementById("ng-status");
    if (!el) return;
    el.textContent = text;
    el.style.color = isError ? "#dd2b0e" : "";
  }

  function nextURL() {
    var p = new URLSearchParams(location.search).get("next");
    return p && p.charAt(0) === "/" && p.charAt(1) !== "/" ? p : "/";
  }

  function initSigninPage(stored) {
    var form = document.getElementById("ng-register-form");
    var existing = document.getElementById("ng-existing");
    if (!form) return;
    if (!window.crypto || !crypto.subtle || !window.indexedDB) {
      setStatus("This browser cannot hold a device key here. Use HTTPS (or localhost) in a modern browser.", true);
      form.classList.add("hidden");
      return;
    }
    if (stored) {
      form.classList.add("hidden");
      if (existing) {
        existing.classList.remove("hidden");
        var n = document.getElementById("ng-existing-name");
        if (n) n.textContent = "@" + stored.username;
      }
      var btn = document.getElementById("ng-signin-btn");
      if (btn) btn.addEventListener("click", function () {
        localStorage.removeItem(SIGNED_OUT);
        setStatus("Signing in with this device...");
        login(stored).then(function (res) {
          if (res._status === 200) { location.href = nextURL(); return; }
          setStatus(res.error || "Sign-in failed", true);
          if (res.code === "unknown_device") offerReset();
        }).catch(function (e) { setStatus(String(e), true); });
      });
      return;
    }
    form.addEventListener("submit", function (ev) {
      ev.preventDefault();
      var name = form.querySelector("input[name=username]").value.trim().toLowerCase();
      setStatus("Generating a key that never leaves this device...");
      form.querySelector("button").disabled = true;
      register(name).then(function () {
        localStorage.removeItem(SIGNED_OUT);
        location.href = nextURL();
      }).catch(function (e) {
        form.querySelector("button").disabled = false;
        setStatus(e.message || String(e), true);
      });
    });
  }

  function offerReset() {
    var r = document.getElementById("ng-reset");
    if (!r) return;
    r.classList.remove("hidden");
    r.querySelector("button").addEventListener("click", function () {
      deleteKey().then(function () { location.reload(); });
    });
  }

  function wireCopyButtons() {
    document.querySelectorAll("[data-copy]").forEach(function (b) {
      b.addEventListener("click", function () {
        var target = document.getElementById(b.getAttribute("data-copy"));
        var text = target ? (target.value || target.textContent) : "";
        if (navigator.clipboard) navigator.clipboard.writeText(text.trim());
        var old = b.textContent; b.textContent = "Copied"; setTimeout(function () { b.textContent = old; }, 1200);
      });
    });
    document.querySelectorAll("form[data-signout]").forEach(function (f) {
      f.addEventListener("submit", function () { localStorage.setItem(SIGNED_OUT, "1"); });
    });
    document.querySelectorAll("[data-confirm]").forEach(function (el) {
      el.addEventListener("click", function (ev) { if (!confirm(el.getAttribute("data-confirm"))) ev.preventDefault(); });
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    wireCopyButtons();
    var signedIn = document.body.getAttribute("data-signed-in") === "1";
    if (!window.indexedDB || !window.crypto || !crypto.subtle) { initSigninPage(null); return; }
    loadKey().then(function (stored) {
      var badge = document.getElementById("ng-device-hint");
      if (badge && stored && !signedIn) badge.textContent = "Sign in as @" + stored.username;
      if (document.getElementById("ng-register-form")) { initSigninPage(stored); return; }
      // Silent automatic sign-in on any page when this device holds a key.
      if (!signedIn && stored && !localStorage.getItem(SIGNED_OUT) && !sessionStorage.getItem("ng-tried")) {
        sessionStorage.setItem("ng-tried", "1");
        login(stored).then(function (res) {
          if (res._status === 200) { sessionStorage.removeItem("ng-tried"); location.reload(); }
        }).catch(function () {});
      }
      if (signedIn) sessionStorage.removeItem("ng-tried");
    }).catch(function () {});
  });
})();
